package com.trustcal.entity;

/**
 * Where the AI agent's advice comes from. Chosen by the researcher on the dashboard and
 * recorded on every participant, so that data from different modes are never mixed silently.
 */
public enum AgentMode {
    /** Advice written in advance by the researcher; the agent's accuracy is fully controlled. */
    SCRIPTED("Scripted agent"),
    /** Advice generated by the LLM in an evaluation run, reviewed and frozen by the researcher. */
    LLM_FROZEN("LLM, pre-generated and frozen"),
    /** Advice generated by the LLM at the moment the participant commits an answer. */
    LLM_LIVE("LLM, generated live");

    private final String label;

    AgentMode(String label) {
        this.label = label;
    }

    public String getLabel() {
        return label;
    }

    public boolean usesLlm() {
        return this != SCRIPTED;
    }
}
